    function Majority_F (bits : Bool[]) : Bool[] {
        let a = bits[0];
        let b = bits[1];
        let c = bits[2];
        let ab = Xor(a, b);
        let ac = Xor(a, c);
        let cout = Xor(ab and ac, a);
        return [cout, ab, ac];
    }


