        ApplyToEachA(Majority_Reference, Zipped3(a, b, carries));

        // No need to save last (N+1)th carry bit

        // Restore inputs and ancilla, compute sum
        ApplyToEachA(UnMajorityAdd_Reference, Reversed(Zipped3(a, b, carries)));
    }

